/// The densities (`@qeetrix/tokens`' density modifier) and the sizes each sets. On the web a
/// region sets one with `data-qx-density`; here a view sets one with `qeetrixDensity(_:)`.
public enum QeetrixDensity: String, CaseIterable, Sendable {
    case `default`
    case comfortable
    case compact

    /// `size.control.sm` · `--qx-size-control-sm`
    ///
    /// In points, per density.
    public var sizeControlSm: CGFloat {
        switch self {
        case .default: 28
        case .comfortable: 32
        case .compact: 24
        }
    }

    /// `size.control.md` · `--qx-size-control-md`
    ///
    /// In points, per density.
    public var sizeControlMd: CGFloat {
        switch self {
        case .default: 32
        case .comfortable: 36
        case .compact: 28
        }
    }

    /// `size.control.lg` · `--qx-size-control-lg`
    ///
    /// In points, per density.
    public var sizeControlLg: CGFloat {
        switch self {
        case .default: 40
        case .comfortable: 44
        case .compact: 32
        }
    }

    /// `size.row` · `--qx-size-row`
    ///
    /// In points, per density.
    public var sizeRow: CGFloat {
        switch self {
        case .default: 40
        case .comfortable: 48
        case .compact: 32
        }
    }

    /// `space.form.gap` · `--qx-space-form-gap` ({primitive.space.400})
    ///
    /// In points, per density.
    public var spaceFormGap: CGFloat {
        switch self {
        case .default: 16
        case .comfortable: 20
        case .compact: 12
        }
    }
}

