/// The bundled typefaces: the web's own fonts, as the TTFs `@qeetrix/tokens` ships for native platforms.
public enum QeetrixFontFamily: String, CaseIterable, Sendable {
    /// Qeet Sans on the web: Cal Sans, Version 2.011; 5a149ee7, from @qeetrix/tokens `package/dist/fonts/QeetSans.ttf`.
    case sans

    /// Fira Code on the web: Fira Code, Version 6.002, from @qeetrix/tokens `package/dist/fonts/FiraCode-VF.ttf`.
    case mono

    /// The bundled font file and its variation axes, as read from the font at generation time.
    public var face: QeetrixFontFace {
        switch self {
        case .sans:
            QeetrixFontFace(
                resourceName: "QeetSans",
                postScriptName: "CalSans-Regular",
                familyName: "Cal Sans",
                webFamily: "Qeet Sans",
                axes: [
                    QeetrixFontAxis(tag: "opsz", minimum: 8, defaultValue: 14, maximum: 45),
                    QeetrixFontAxis(tag: "GEOM", minimum: 0, defaultValue: 25, maximum: 100),
                    QeetrixFontAxis(tag: "wght", minimum: 400, defaultValue: 400, maximum: 700),
                    QeetrixFontAxis(tag: "YTAS", minimum: 1440, defaultValue: 1440, maximum: 1600),
                    QeetrixFontAxis(tag: "SHRP", minimum: 0, defaultValue: 0, maximum: 100),
                    QeetrixFontAxis(tag: "ital", minimum: 0, defaultValue: 0, maximum: 1)
                ])
        case .mono:
            QeetrixFontFace(
                resourceName: "FiraCode-VF",
                postScriptName: "FiraCode-Light",
                familyName: "Fira Code",
                webFamily: "Fira Code",
                axes: [
                    QeetrixFontAxis(tag: "wght", minimum: 300, defaultValue: 300, maximum: 700)
                ])
        }
    }
}
